def is_palindrome(s):
    left, right = 0, len(s) - 1
    while left < right:
        while left < right and not s[left].isalnum():
            left += 1
        while left < right and not s[right].isalnum():
            right -= 1
        if s[left].lower() != s[right].lower():
            return False
        left += 1
        right -= 1
    return True

def length_of_longest_substring(s):
    last_seen = {}
    left = 0
    longest = 0
    for right, ch in enumerate(s):
        if ch in last_seen and last_seen[ch] >= left:
            left = last_seen[ch] + 1
        last_seen[ch] = right
        longest = max(longest, right - left + 1)
    return longest

from collections import Counter

def min_window(s, t):
    if not s or not t:
        return ""
    need = Counter(t)
    missing = len(t)  # total characters still needed (with multiplicity)
    left = 0
    best_left, best_len = 0, float('inf')

    for right, ch in enumerate(s):
        if need[ch] > 0:
            missing -= 1
        need[ch] -= 1

        while missing == 0:
            if right - left + 1 < best_len:
                best_left, best_len = left, right - left + 1
            left_ch = s[left]
            need[left_ch] += 1
            if need[left_ch] > 0:
                missing += 1
            left += 1

    return "" if best_len == float('inf') else s[best_left:best_left + best_len]

from collections import Counter

def find_anagrams(s, p):
    if len(p) > len(s):
        return []

    need = Counter(p)
    window = Counter()
    required = len(need)
    formed = 0
    result = []
    left = 0

    for right, ch in enumerate(s):
        window[ch] += 1
        if ch in need and window[ch] == need[ch]:
            formed += 1

        if right - left + 1 > len(p):
            left_ch = s[left]
            if left_ch in need and window[left_ch] == need[left_ch]:
                formed -= 1
            window[left_ch] -= 1
            left += 1

        if right - left + 1 == len(p) and formed == required:
            result.append(left)

    return result

def triangle_number(nums):
    nums.sort()
    n = len(nums)
    count = 0

    for k in range(n - 1, 1, -1):
        i, j = 0, k - 1
        while i < j:
            if nums[i] + nums[j] > nums[k]:
                count += j - i  # every index from i..j-1 paired with j also works
                j -= 1
            else:
                i += 1

    return count
